import*as THREE from"three";const scene=new THREE.Scene,camera=new THREE.PerspectiveCamera(75,window.innerWidth/window.innerHeight,.1,1e3),renderer=new THREE.WebGLRenderer;renderer.setSize(window.innerWidth,window.innerHeight),renderer.setAnimationLoop(animate),document.body.appendChild(renderer.domElement);const geometry=new THREE.BoxGeometry(1,1,1),material=new THREE.MeshBasicMaterial({color:65280}),cube=new THREE.Mesh(geometry,material);function animate(){cube.rotation.x+=.01,cube.rotation.y+=.01,renderer.render(scene,camera)}scene.add(cube),camera.position.z=5;